  <script type="module">
    // Pretext-powered text reflow for metric tiles and card titles
    const { prepare, layout } = window.Pretext;
    await document.fonts.ready;

    const pretextElements = document.querySelectorAll('[data-pretext]');
    const prepared = new Map();

    for (const el of pretextElements) {
      const font = getComputedStyle(el).font;
      prepared.set(el, prepare(el.textContent, font));
    }

    function relayout() {
      for (const [el, handle] of prepared) {
        const lineHeight = parseFloat(getComputedStyle(el).lineHeight);
        const { height } = layout(handle, el.clientWidth, lineHeight);
        el.style.height = `${height}px`;
      }
    }

    const ro = new ResizeObserver(() => relayout());
    ro.observe(document.body);
    relayout();

    for (const el of pretextElements) {
      if (el.contentEditable === 'true') {
        new MutationObserver(() => {
          const font = getComputedStyle(el).font;
          prepared.set(el, prepare(el.textContent, font));
          relayout();
        }).observe(el, { characterData: true, subtree: true, childList: true });
      }
    }
  </script>

